package hartland

model db schema dbo

// AU (automation agents) — the H-1 order extension + the H-3/H-5 write-back tables (D-79, D-81…D-83).
// Physical spellings: project/kantheon/features/automation-agents/implementation/hartland/contracts.md §1.
// Built in BOTH worlds by `data/automation/` (step 9 of the data build, hartland P1), derived from the
// TPC-DS facts already loaded, so the two worlds get identical DDL:
//
//   sales_order        one row per distinct web_sales.ws_order_number / catalog_sales.cs_order_number
//                      (the header: channel, customer, warehouse, value, the H-1 state)
//   sales_line         one row per web_sales ∪ catalog_sales line; line_no = row_number by item_sk
//   price_list         the item's modal unit price per channel, open-ended + planted closed windows
//   customer_price     a hash-selected ~2 % of the (customer, item) pairs with lines
//   invoice            one per order in state `released`; payment behaviour by a customer hash
//   warehouse_outage   a handful of outage days per distribution center per year
//   reorder_proposal   H-3's proposals — EMPTY at build; written by the recipe (`writable:`, D-79)
//   winback_mail       H-5's mailed customers — EMPTY at build; written by the recipe (`writable:`)
//
// Money is decimal(12,2) — wider than the facts' (10,2): CZK values of multi-line orders exceed 10
// digits. Dates are real `date`s, never date_dim sks (D-82); the only sks are foreign keys to dimensions.
// Text is `varchar` (the DDL's `text`, the dims.ttrm precedent). Every enumeration below is a plain text
// column; the TTR-M `states:` keyword arrives with ttr-core P0 and is added at hartland P2·S2.1.

def table sales_order {
    // `order` is reserved in SQL: the entity is `order`, the table `sales_order` (D-119).
    description: "Order headers (AU H-1) — one row per web or marketplace order. so_state: placed · held · released · cancelled; so_held_for: Sales · AR · both."
    primaryKey: [so_order_number]
    columns: [
        def column so_order_number   { type: int, isKey: true },
        def column so_channel        { type: varchar },                                       // web · marketplace
        def column so_customer_sk    { type: int },
        def column so_placed_date    { type: date },
        def column so_delivered_date { type: date },                                          // NULL until delivered
        def column so_warehouse_sk   { type: int },                                           // the fulfilling distribution center
        def column so_value          { type: { type: decimal, length: 12, precision: 2 } },
        def column so_state          { type: varchar },
        def column so_held_for       { type: varchar },                                       // NULL unless held
        def column so_placed_by      { type: varchar }
    ]
}

def table sales_line {
    description: "Order lines (AU H-1, D-81) — one row per web_sales ∪ catalog_sales line, numbered within its order by item."
    primaryKey: [sl_order_number, sl_line_no]
    columns: [
        def column sl_order_number    { type: int, isKey: true },
        def column sl_line_no         { type: int, isKey: true },
        def column sl_item_sk         { type: int },
        def column sl_quantity        { type: int },
        def column sl_unit_price      { type: { type: decimal, length: 12, precision: 2 } },
        def column sl_ext_sales_price { type: { type: decimal, length: 12, precision: 2 } },
        def column sl_warehouse_sk    { type: int },
        def column sl_sold_date       { type: date },
        def column sl_customer_sk     { type: int },
        def column sl_channel         { type: varchar }                                       // web · marketplace
    ]
}

def table price_list {
    description: "Channel price list (AU H-1) — the list price of an item in a channel over a validity window; pl_valid_to NULL = open-ended."
    primaryKey: [pl_item_sk, pl_channel, pl_valid_from]
    columns: [
        def column pl_item_sk    { type: int, isKey: true },
        def column pl_channel    { type: varchar, isKey: true },
        def column pl_valid_from { type: date, isKey: true },
        def column pl_price      { type: { type: decimal, length: 12, precision: 2 } },
        def column pl_valid_to   { type: date }
    ]
}

def table customer_price {
    description: "Individual customer prices (AU H-1) — a customer's own price of an item over a validity window; beats the channel price list."
    primaryKey: [cp_item_sk, cp_customer_sk, cp_valid_from]
    columns: [
        def column cp_item_sk     { type: int, isKey: true },
        def column cp_customer_sk { type: int, isKey: true },
        def column cp_valid_from  { type: date, isKey: true },
        def column cp_price       { type: { type: decimal, length: 12, precision: 2 } },
        def column cp_valid_to    { type: date }
    ]
}

def table invoice {
    description: "Invoices (AU H-1) — one per released order. inv_status: open · paid."
    primaryKey: [inv_invoice_id]
    columns: [
        def column inv_invoice_id   { type: int, isKey: true },
        def column inv_customer_sk  { type: int },
        def column inv_order_number { type: int },
        def column inv_issued       { type: date },
        def column inv_due          { type: date },
        def column inv_amount       { type: { type: decimal, length: 12, precision: 2 } },
        def column inv_paid         { type: { type: decimal, length: 12, precision: 2 } },
        def column inv_status       { type: varchar }
    ]
}

def table warehouse_outage {
    description: "Distribution-center outages (AU H-1) — a center that cannot ship from wo_from_date to wo_to_date (both inclusive)."
    primaryKey: [wo_warehouse_sk, wo_from_date]
    columns: [
        def column wo_warehouse_sk { type: int, isKey: true },
        def column wo_from_date    { type: date, isKey: true },
        def column wo_to_date      { type: date },
        def column wo_reason       { type: varchar }
    ]
}

def table reorder_proposal {
    // `bigserial` in the DDL — TTR-M has no bigint, and `int` reads it correctly at demo volumes.
    description: "Reorder proposals (AU H-3) — written by the reorder_proposals recipe, empty at build. rp_state: proposed · approved · rejected · started."
    primaryKey: [rp_proposal_id]
    columns: [
        def column rp_proposal_id   { type: int, isKey: true },
        def column rp_run           { type: varchar },                                         // the automation run that proposed it
        def column rp_item_sk       { type: int },
        def column rp_warehouse_sk  { type: int },
        def column rp_on_hand       { type: int },
        def column rp_weekly_demand { type: { type: decimal, length: 12, precision: 2 } },
        def column rp_proposed_qty  { type: int },
        def column rp_state         { type: varchar }
    ]
}

def table winback_mail {
    description: "Win-back mailings (AU H-5) — the customers the winback recipe mailed, one row per customer and quarter; empty at build. wm_offer: premium · standard."
    primaryKey: [wm_customer_sk, wm_quarter]
    columns: [
        def column wm_customer_sk { type: int, isKey: true },
        def column wm_quarter     { type: varchar, isKey: true },                              // e.g. 2026-Q4
        def column wm_offer       { type: varchar },
        def column wm_run         { type: varchar },                                         // the automation run that mailed it
        def column wm_mailed_at   { type: timestamp }                                        // timestamptz in the DDL
    ]
}

files.model/db/returns-flow.ttrm:
package hartland

model db schema dbo

// AU (automation agents) — the H-2 return-request flow (D-79, D-84). Physical spellings:
// project/kantheon/features/automation-agents/implementation/hartland/contracts.md §1.
// Built in BOTH worlds by `data/automation/` (hartland P1) from the existing *_returns facts: requests +
// lines from the returns, most requests single-line; receipts, credit notes, payments and replacement
// shipments generated for decided requests WITH planted gaps (D-79: the ERP fulfils imperfectly). The
// generator is the ERP here: it writes the four document tables; the recipes only ever expect them.
//
// The H-2 key is the LINE (D-84). The request header's state is not stored — the `return_request` view
// derives it from its lines. Every enumeration is a plain text column (`states:` arrives at P2·S2.1).

def table return_request_hdr {
    description: "Return-request headers (AU H-2) — who returns what order through which channel, and when it was requested. The entity reads the return_request VIEW, which adds the derived state."
    primaryKey: [rr_request_number]
    columns: [
        def column rr_request_number { type: int, isKey: true },
        def column rr_customer_sk    { type: int },
        def column rr_order_number   { type: int },
        def column rr_channel        { type: varchar },                                          // web · marketplace
        def column rr_requested_date { type: date }
    ]
}

def table return_request_line {
    // rl_customer_sk is the request's customer, DENORMALIZED onto the line by the generator (D-127): a
    // relation is one hop, and H-2 joins the line to its customer's center (17 §4.1, rel_line_customer).
    description: "Return-request lines (AU H-2, the key of the flow, D-84). rl_state: received · rejected · settling · awaiting_goods · goods_received · not_returned · closed."
    primaryKey: [rl_line_id]
    columns: [
        def column rl_line_id              { type: int, isKey: true },
        def column rl_request_number       { type: int },
        def column rl_line_no              { type: int },
        def column rl_item_sk              { type: int },
        def column rl_quantity             { type: int },
        def column rl_unit_price           { type: { type: decimal, length: 12, precision: 2 } },
        def column rl_reason               { type: varchar },                                   // damaged · did_not_arrive · wrong_size · other
        def column rl_requested_resolution { type: varchar },                                   // refund · exchange · replacement
        def column rl_requested_variant_sk { type: int },                                       // NULL unless an exchange names a variant
        def column rl_state                { type: varchar },
        def column rl_way                  { type: varchar },                                   // NULL until decided — the decide_return route taken
        def column rl_customer_sk          { type: int }
    ]
}

def table return_receipt {
    description: "Returned goods received (AU H-2) — written by the ERP (the generator; live, the n8n ERP workflow). rc_condition: ok · damaged · missing."
    primaryKey: [rc_receipt_id]
    columns: [
        def column rc_receipt_id    { type: int, isKey: true },
        def column rc_line_id       { type: int },
        def column rc_received_date { type: date },
        def column rc_item_sk       { type: int },
        def column rc_quantity      { type: int },
        def column rc_condition     { type: varchar }
    ]
}

def table credit_note {
    description: "Credit notes issued for return lines (AU H-2) — written by the ERP. cn_status: issued · paid."
    primaryKey: [cn_credit_note_id]
    columns: [
        def column cn_credit_note_id { type: int, isKey: true },
        def column cn_line_id        { type: int },
        def column cn_customer_sk    { type: int },
        def column cn_issued_date    { type: date },
        def column cn_amount         { type: { type: decimal, length: 12, precision: 2 } },
        def column cn_status         { type: varchar }
    ]
}

def table refund_payment {
    description: "Refunds paid out against credit notes (AU H-2) — written by the ERP."
    primaryKey: [rp_payment_id]
    columns: [
        def column rp_payment_id     { type: int, isKey: true },
        def column rp_credit_note_id { type: int },
        def column rp_paid_date      { type: date },
        def column rp_amount         { type: { type: decimal, length: 12, precision: 2 } }
    ]
}

def table replacement_shipment {
    description: "Replacement goods shipped for return lines (AU H-2) — written by the ERP."
    primaryKey: [rs_shipment_id]
    columns: [
        def column rs_shipment_id  { type: int, isKey: true },
        def column rs_line_id      { type: int },
        def column rs_item_sk      { type: int },
        def column rs_quantity     { type: int },
        def column rs_shipped_date { type: date }
    ]
}

// Derived VIEWS — `data/views/return_request.sql` and `data/views/document_flow.sql` (hartland P1·S1.1)
// copy the SQL below; the channel_sales precedent (views.ttrm): the model says what the view IS.
// Column order is load-bearing — CREATE OR REPLACE VIEW can only APPEND a column.

def view return_request {
    // D-84: `received` while any line is received (or none has arrived yet); `closed` when every line is
    // rejected, not_returned or closed; `decided` in between. Nothing writes it — the recipes write lines.
    description: "Return requests (AU H-2) — the header with its state derived from its lines: received · decided · closed."
    columns: [
        def column rr_request_number { type: int },
        def column rr_customer_sk    { type: int },
        def column rr_order_number   { type: int },
        def column rr_channel        { type: varchar },
        def column rr_requested_date { type: date },
        def column rr_state          { type: varchar }
    ]
    definitionSql: """
        SELECT h.rr_request_number, h.rr_customer_sk, h.rr_order_number, h.rr_channel, h.rr_requested_date,
               CASE WHEN COUNT(l.rl_line_id) = 0 OR BOOL_OR(l.rl_state = 'received') THEN 'received'
                    WHEN BOOL_AND(l.rl_state IN ('rejected', 'not_returned', 'closed')) THEN 'closed'
                    ELSE 'decided'
               END::text AS rr_state
          FROM return_request_hdr h
          LEFT JOIN return_request_line l ON l.rl_request_number = h.rr_request_number
         GROUP BY h.rr_request_number, h.rr_customer_sk, h.rr_order_number, h.rr_channel, h.rr_requested_date
    """
}

def view document_flow {
    description: "The document flow of a return (AU H-2) — which document followed which: order → request, request → receipt, request → credit note, credit note → refund payment, request → replacement shipment. Kinds are entity names."
    columns: [
        def column df_pred_kind { type: varchar },
        def column df_pred_id   { type: int },
        def column df_succ_kind { type: varchar },
        def column df_succ_id   { type: int }
    ]
    definitionSql: """
        SELECT 'order'::text AS df_pred_kind, rr_order_number AS df_pred_id,
               'return_request'::text AS df_succ_kind, rr_request_number AS df_succ_id
          FROM return_request_hdr
        UNION ALL
        SELECT 'return_request', l.rl_request_number, 'return_receipt', rc.rc_receipt_id
          FROM return_receipt rc JOIN return_request_line l ON l.rl_line_id = rc.rc_line_id
        UNION ALL
        SELECT 'return_request', l.rl_request_number, 'credit_note', cn.cn_credit_note_id
          FROM credit_note cn JOIN return_request_line l ON l.rl_line_id = cn.cn_line_id
        UNION ALL
        SELECT 'credit_note', rp_credit_note_id, 'refund_payment', rp_payment_id
          FROM refund_payment
        UNION ALL
        SELECT 'return_request', l.rl_request_number, 'replacement_shipment', rs.rs_shipment_id
          FROM replacement_shipment rs JOIN return_request_line l ON l.rl_line_id = rs.rs_line_id
    """
}

files.model/db/views.ttrm:
package hartland

model db schema dbo

// Physical VIEWS — created by `data/views/*.sql` in both worlds (hartland_us, hartland_cz); the
// model declares what the database already holds. `definitionSql` mirrors the script so the model
// says what the view IS, not only what it is called.

def view channel_sales {
    description: "All-channel sales lines — store, web and marketplace sales in one relation, labelled by channel. The one object on which revenue and units sold can be asked BY CHANNEL."
    columns: [
        def column channel          { type: varchar },
        def column sold_date_sk     { type: int },
        def column item_sk          { type: int },
        def column customer_sk      { type: int },
        def column quantity         { type: int },
        def column ext_sales_price  { type: { type: decimal, length: 10, precision: 2 } },
        // LR ⚑LR-9 — the fulfilling DC of a web / marketplace line; NULL on a store line. The
        // DC-scope row rule filters on it (contracts C-5·4). Last, as in the script.
        def column warehouse_sk     { type: int }
    ]
    definitionSql: """
        SELECT 'store'::text AS channel, ss_sold_date_sk AS sold_date_sk, ss_item_sk AS item_sk,
               ss_customer_sk AS customer_sk, ss_quantity AS quantity, ss_ext_sales_price AS ext_sales_price,
               NULL::int AS warehouse_sk
          FROM store_sales
        UNION ALL
        SELECT 'web', ws_sold_date_sk, ws_item_sk, ws_bill_customer_sk, ws_quantity, ws_ext_sales_price, ws_warehouse_sk
          FROM web_sales
        UNION ALL
        SELECT 'marketplace', cs_sold_date_sk, cs_item_sk, cs_bill_customer_sk, cs_quantity, cs_ext_sales_price, cs_warehouse_sk
          FROM catalog_sales
    """
}

files.model/er/calendar.ttrm:
package hartland

model er

// Calendar (D-5) — everything joins through it; holiday/seasonality live here.
// Not listed in the Stage 2.2 task file's suggested layout (it groups date_dim into no
// named file) — broken out into its own file since it backs the md Calendar dimension
// (Stage 2.3), which is calc-backed rather than table-backed like the others.

def entity date_dim {
    description: "Calendar."
    codeAttribute: sk
    nameAttribute: cal_date
    roles: [dimension]
    displayLabel: { en: "Calendar", cs: "Kalendář" }
    attributes: [
        def attribute sk        { type: int, isKey: true, description: "Sequence key; the primary key for this entity, not bearing any meaning." },
        // `event_date` is what chrono's anchor-column discovery looks for (MetaV1SemanticDiscovery):
    // it scans the package for an attribute carrying the role and filters the grounded interval
    // on it. It lives HERE and not on a fact's `sold_date` because every fact dates itself by a
    // surrogate key (`type: int` -> date_dim.sk), and the role carries `typeConstraint: 'date'`
    // — an int FK is rejected by the validator, correctly. Every fact reaches this column through
    // its declared `rel_*_date` relation, so one role annotation dates the whole estate.
    def attribute cal_date  { type: date, semantics { role: event_date }, description: "Calendar date. The primary grain of the calendar." },
        def attribute year      { type: int, description: "Derived Year of the calendar date." },
        def attribute month     { type: int, description: "Derived Month of the calendar date." },
        def attribute quarter   { type: int, description: "Derived Quarter of the calendar date." },
        def attribute week_seq  { type: int, description: "Absolute  week number from the beginning of this calendar." },
        def attribute day_name  { type: text, description: "Name of the day of the week. English only" },
        def attribute holiday   { type: { type: char, length: 1 }, description: "Is this a holiday? Y/N" },
        def attribute weekend   { type: { type: char, length: 1 }, description: "Is this a weekend? Y/N" },
        // AU D-82 — what working_days(…) counts in the automation recipes.
        def attribute working_day { type: bool, description: "Is this a working day? True when the day is neither a holiday nor a weekend." }
    ]
}

files.model/er/catalog.ttrm:
package hartland

model er

// Products (the bilingual catalog, Phase 1), Promotions, and Seller Support Centers (D-5).
//
// NLS-P10 (⚑GXP-D7, grammar 0.13) — this file is the estate's BILINGUAL EXEMPLAR: every
// `description:` here is authored as a localised map instead of a plain string, so a
// `GetModel(locale: "cs")` serves Czech and a `GetModel(locale: "en")` serves English off
// one model. The rest of `model/er/` stays plain-string on purpose: both forms are legal
// side by side, and the mix is what proves it.
//
// The chain a reader applies (Veles, D7): requested locale → plain form → `en` → first
// entry by language code → "". Writing both locales here means step 1 always hits.

def entity item {
    description: {
        en: "Products — category/brand drills; the bilingual catalog lit these up (Phase 1).",
        cs: "Produkty — členění podle kategorie a značky; dvojjazyčný katalog je rozsvítil (fáze 1)."
    }
    labelPlural: "Products"
    // LP-P3·T1 (LP contracts §2.1) — the mention facet a quoted literal attributes to:
    // `"..."` on this head lands on `name`, a code-shaped literal on `code`. Without it the
    // literal is headless (G3) and the fast path refuses. The legacy properties below are
    // kept for the same reason store's are (readers before producers).
    semantics { name: product_name, code: item_id, code_pattern: "^[A-P]{16}$" }
    nameAttribute: product_name
    codeAttribute: item_id
    roles: [dimension]
    displayLabel: { en: "Product", cs: "Produkt" }
    attributes: [
        def attribute sk           { type: int, isKey: true, description: { en: "Sequence key. Internal primary key only.", cs: "Sekvenční klíč. Pouze interní primární klíč." } },
        def attribute item_id      { type: text, description: { en: "Unique product identifier. Code. One SKU.", cs: "Jedinečný identifikátor produktu. Kód. Jedna SKU." } },
        // A member vocabulary (18 000 rows, 17 952 names): a quoted partial name — products «Voltaic» —
        // finds the product by its words. TOKENS: a catalogue name is several words and users type one.
        def attribute product_name { type: text, description: { en: "Product name, the human-readable label.", cs: "Název produktu, čitelné označení." }, search { searchable method: TOKENS } },
        def attribute brand        { type: text, description: { en: "Product brand of this item", cs: "Značka tohoto produktu" } },
        def attribute class        { type: text, description: { en: "Product class of this item", cs: "Třída tohoto produktu" } },
        def attribute category     { type: text, description: { en: "Product category of this item", cs: "Kategorie tohoto produktu" } },
        def attribute manufact     { type: text, description: { en: "The manufacturer of this item", cs: "Výrobce tohoto produktu" } },
