files.model/er/customer_revenue.ttrm:
package hartland

model er

// LQ — logical queries (ttr-core#191, ttr-server#245). A saved query written over ENTITIES, and an
// entity stacked on it. Declared in a `model er` file, the query is the logical query
// `er.query.revenue_per_customer`: its body names entities and attributes, never tables, and its bare
// `JOIN` is conditioned by the model — here from `rel_channel_sales_customer`'s foreign key (the
// FK-only relation needs no `join:` pairs for that). The entity `customer_revenue` reads the query;
// agents are meant to ask over the entity only (LQ-6).
//
// ⚑ The query is NOT named after the entity. veles 0.11.11 still lists a logical query in ListQueries
// and in GetModel's namedQueries (so meta-mcp `list_queries` offers it, and running it is refused with
// `query_ref_logical_query`), and golem's descriptor lookup tries a query's LOCAL name before an
// entity's. A query called `customer_revenue` would answer for the entity there; a name of its own
// cannot.
//
// Why a query: "average customer revenue by household buying potential" is an aggregate OF an
// aggregate — revenue summed per customer, then averaged per band. Over `channel_sales` that is a
// nested query no agent should have to write; over `customer_revenue` it is a plain AVG.
//
// Security rides along: the body reads `channel_sales`, which the DC-scope row rule (olymp, validate
// `dc-scope`) narrows for a `kantheon-scope-dc-5` caller to DC 5's web and marketplace lines. The body
// is inlined into the plan where the entity is read, so that caller's customer revenue counts only
// those lines — Sam's and Maya's answers to the same question differ.
//
// ALL TIME: the body sums every line on record and keeps no date, so the entity has no date attribute
// and no relation to the calendar. "Average customer revenue in 2025" cannot be narrowed to 2025 on
// it; the descriptions say so, so the answer is not lifetime figures labelled as one year.

def query revenue_per_customer {
    description: "All-time revenue per customer across all channels — one row per customer, with the customer's household and year of birth. No period: every sale on record."
    tags: ["sales", "customers"]
    sourceText: """sql
SELECT customer.sk, customer.customer_id, customer.hdemo, customer.birth_year,
       SUM(channel_sales.ext_sales_price) AS revenue
FROM channel_sales JOIN customer
GROUP BY customer.sk, customer.customer_id, customer.hdemo, customer.birth_year
"""
}

// Stacked on the query: its attributes bind to the query's OUTPUT columns — unbound, so each names
// the column of its own name (the metadata service checks them against the query's output when it
// parses the body). It has no foreign key, so its relations state `join:` pairs.
//
// The label names the OBJECT, not the measure phrase: a label is a METADATA term and outranks any
// declared phrase (ttr-demo#62), so "Customer Revenue" as a label would bind the entity where the
// measure is meant. "customer revenue" is declared on the measure in `lexicon/aliases/hartland.lex.yaml`.
//
// No `code:` facet: `customer` already carries `customer_id` as its code, and a second head with the
// same pattern would split a code-shaped literal ("AAAAAAAABAAAAAAA") between the two. The literal
// lands on `customer`, and `rel_customer_revenue_customer` reaches this entity from there.
def entity customer_revenue {
    description: "Customer revenue totals, ALL TIME — one row per customer: the customer's revenue across all channels (store, web, marketplace) over every sale on record, their household and year of birth. Average, rank or band it across customers; it is already a SUM per customer. It has no date: a question about one year, quarter or month cannot be answered from it."
    labelPlural: "Customer Totals"
    roles: [fact]
    displayLabel: { en: "Customer Totals", cs: "Souhrny zákazníků" }
    semantics { measures: [ revenue ] }
    binding: { target: { query: er.query.revenue_per_customer } },
    attributes: [
        def attribute sk          { type: int, isKey: true, description: "Customer sequence key — the 'sk' attribute of the Customer entity. Internal key only." },
        def attribute customer_id { type: text, description: "Unique customer identifier (code)." },
        def attribute hdemo       { type: int, description: "Household demographics — FK to the 'sk' attribute of the Household Demographics entity." },
        def attribute birth_year  { type: int, description: "Customer's year of birth — buyer-age analyses derive age from this." },
        def attribute revenue     { type: { type: decimal, length: 12, precision: 2 }, description: "The customer's all-time revenue across all channels — the SUM of every one of their lines' ext_sales_price, no period." }
    ]
}

def relation rel_customer_revenue_hdemo {
    description: "A customer's revenue total belongs to the customer's household demographics."
    from: er.entity.customer_revenue, to: er.entity.household_demographics,
    cardinality: { from: "0..*", to: "1" },
    join: [{ from: er.entity.customer_revenue.hdemo, to: er.entity.household_demographics.sk }]
}

def relation rel_customer_revenue_customer {
    description: "A customer's revenue total is the total of one customer."
    from: er.entity.customer_revenue, to: er.entity.customer,
    cardinality: { from: "0..1", to: "1" },
    join: [{ from: er.entity.customer_revenue.sk, to: er.entity.customer.sk }]
}

files.model/er/inventory.ttrm:
package hartland

model er

// Inventory Snapshots — the smoking gun (S1) — and its Distribution Center dim (D-5).

def entity inventory {
    description: "Weekly warehouse-level on-hand snapshots per warehouse and item."
    roles: [fact]
    displayLabel: { en: "Inventory Snapshots", cs: "Stavy zásob" }
    // MS: the mention facet. ⚠ `last`, NOT the bare-id default `sum` (Bora, 2026-09-16):
    // this fact is only semi-additive — see as_of_date, "stock levels MUST NOT be added
    // across snapshots" — so a bare `quantity_on_hand` would declare precisely the
    // aggregation the model forbids. The per-measure `aggregation:` here is the measure's
    // own (semantics vocabulary v3); it is neither the def-level `aggregation:` property
    // nor md's, which are separate surfaces by design.
    semantics { measures: [{ attribute: quantity_on_hand, aggregation: last }] }
    attributes: [
        def attribute as_of_date       { type: int, isKey: true, description: "Weekly snapshot date. This entity is only semi-additive - stock levels MUST NOT be added across snapshots." },
        def attribute item             { type: int, isKey: true, description: "Item primary key (the 'sk' attribute of the Item entity)" },
        def attribute warehouse        { type: int, isKey: true, description: "Warehouse primary key (the 'sk' attribute of the Warehouse entity)" },
        def attribute quantity_on_hand { type: int, description: "Quantity on hand of the given item at the time of the snapshot." }
    ]
}

def entity warehouse {
    description: "Distribution Centers"
    // LP-P3·T1 (LP contracts §2.1) — the mention facet a quoted literal attributes to:
    // `"..."` on this head lands on `name`, a code-shaped literal on `code`. Without it the
    // literal is headless (G3) and the fast path refuses. The legacy properties below are
    // kept for the same reason store's are (readers before producers).
    semantics { name: warehouse_name, code: warehouse_id, code_pattern: "^[A-P]{16}$" }
    nameAttribute: warehouse_name
    codeAttribute: warehouse_id
    roles: [dimension]
    displayLabel: { en: "Distribution Center", cs: "Distribuční centrum" }
    attributes: [
        def attribute sk              { type: int, isKey: true, description: "Warehouse primary key. Internal sequence key only." },
        def attribute warehouse_id    { type: text, description: "Warehouse ID (unique code)" },
        // Member vocabulary, TOKENS: five names (`Memphis DC` …) — «Memphis» alone finds the DC.
        def attribute warehouse_name  { type: text, description: "Warehouse name, the human-readable label", search { searchable method: TOKENS } },
        def attribute city            { type: text, description: "The city the warehouse is located in" },
        // MH-P3 tier M — one of the three attributes holding a `TN`. The value alone cannot
        // say which; the GOVERNOR does ("warehouses in TN"), and that only works if the value
        // is in the member vocabulary at all. EXACT, not TYPOS: on a two-character code every
        // other state is one edit away.
        def attribute state           { type: { type: char, length: 2 }, description: "The state the warehouse is located in", search { searchable method: EXACT } }
    ]
}

files.model/er/orders.ttrm:
package hartland

model er

// AU (automation agents) — the H-1 order extension (D-81…D-83), the entity table of
// project/kantheon/features/automation-agents/design/17-recipes-retyped.md §0: the names the hero recipes
// are written against. Real dates, never date_dim sks (D-82).
//
// Every enumeration is named in the attribute's `description:` and labelled by `valueLabels` (S0.2);
// the TTR-M `states:` keyword arrives with ttr-core P0 and lands on `order.state` and
// `invoice.status` at hartland P2·S2.1.
//
// ⚠ A value label is a MEMBER term of the estate's lexicon, matched in every Golem question — so no label
// here repeats a word the pre-AU vocabulary already binds (model/lexicon/tests/automation-lexicon.test.mjs).
// That is why `held_for` says "Sales department", not "Sales", and why no `channel` attribute is labelled:
// «web», «tržiště», "web", "marketplace" are the channel words of the three sales facts.
//
// ⚠ `sales_line` is the RECIPES' line, not a conversational fact: it declares no `semantics { measures }`.
// The Golem's "revenue by channel" keeps `channel_sales`; a second entity offering the same revenue would
// split every bare "revenue"/"tržby" between two refs (contracts.md §2).

def entity order {
    // `order` is reserved in SQL, so the table is `sales_order`; er2db carries the name (D-119).
    description: "Orders — one web or marketplace order (header): who ordered, through which channel, from which distribution center, its value and where it is in the release process. State: placed · held · released · cancelled."
    labelPlural: "Orders"
    // The mention facet: an order is asked about by its number («why is 4711 held?»). The legacy
    // property beside it is kept for the reason store's is (readers before producers, TTR-SEM-218).
    semantics { code: order_number }
    codeAttribute: order_number
    roles: [transaction]
    displayLabel: { en: "Order", cs: "Objednávka" }
    attributes: [
        def attribute order_number         { type: int, isKey: true, description: "Order number — the web or marketplace order number of the order's lines." },
        def attribute channel              { type: text, description: "Sales channel of the order: 'web' or 'marketplace'." },
        def attribute customer             { type: int, description: "Ordering customer — FK to the 'sk' attribute of the Customer entity." },
        def attribute placed_date          { type: date, description: "The day the order was placed." },
        def attribute delivered_date       { type: date, description: "The day the order was delivered; empty until then." },
        def attribute fulfilling_warehouse { type: int, description: "Distribution center that ships the order — FK to the 'sk' attribute of the Distribution Center (warehouse) entity." },
        def attribute value                { type: { type: decimal, length: 12, precision: 2 }, description: "Order value — the sum of its lines' extended sales prices." },
        def attribute state {
            type: text,
            description: "Release state of the order: 'placed' (waiting for the release check), 'held', 'released' or 'cancelled'.",
            // AU D-67: the lifecycle the automation actions are checked against (`release`, `hold`); held → held is the
            // implicit silent self-transition (D-85).
            states: [placed, held, released, cancelled],
            transitions: { placed: [held, released, cancelled], held: [released, cancelled] },
            valueLabels: {
                "placed":    { en: "Placed",    cs: "Pořízeno" },
                "held":      { en: "Held",      cs: "Pozastaveno" },
                "released":  { en: "Released",  cs: "Uvolněno" },
                "cancelled": { en: "Cancelled", cs: "Zrušeno" }
            }
        },
        def attribute held_for {
            type: text,
            description: "Who a held order waits for: 'Sales', 'AR' or 'both'; empty unless the order is held.",
            valueLabels: {
                "Sales": { en: "Sales department",       cs: "Obchodní oddělení" },
                "AR":    { en: "Receivables department", cs: "Oddělení pohledávek" },
                "both":  { en: "Both departments",       cs: "Obě oddělení" }
            }
        },
        def attribute placed_by            { type: text, description: "Who placed the order (the ordering user or system)." }
    ]
}

def entity sales_line {
    description: "Order lines — one line of a web or marketplace order: the item, quantity, unit and extended price, the shipping distribution center. The release check reads an order's lines; for revenue by channel use All-Channel Sales."
    labelPlural: "Order Lines"
    roles: [fact]
    displayLabel: { en: "Order Line", cs: "Řádek objednávky" }
    attributes: [
        def attribute order_number    { type: int, isKey: true, description: "Order number — FK to the 'order_number' attribute of the Order entity." },
        def attribute line_no         { type: int, isKey: true, description: "Line number within the order." },
        def attribute item            { type: int, description: "Ordered product — FK to the 'sk' attribute of the Product (item) entity." },
        def attribute quantity        { type: int, description: "Units ordered on this line." },
        def attribute unit_price      { type: { type: decimal, length: 12, precision: 2 }, description: "Unit price charged on this line — compared with the price list or the customer's individual price." },
        def attribute ext_sales_price { type: { type: decimal, length: 12, precision: 2 }, description: "Extended sales price of the line (unit price × quantity)." },
        def attribute warehouse       { type: int, description: "Distribution center shipping the line — FK to the 'sk' attribute of the Distribution Center (warehouse) entity." },
        def attribute sold_date       { type: date, description: "The day the line was sold." },
        def attribute customer        { type: int, description: "Ordering customer — FK to the 'sk' attribute of the Customer entity." },
        def attribute channel         { type: text, description: "Sales channel of the line: 'web' or 'marketplace'." }
    ]
}

def entity price_list {
    description: "Channel price list — the list price of a product in a sales channel, valid from valid_from to valid_to (empty valid_to = still valid)."
    labelPlural: "Price Lists"
    roles: [master]
    displayLabel: { en: "Price List", cs: "Ceník" }
    attributes: [
        def attribute item       { type: int, isKey: true, description: "Priced product — FK to the 'sk' attribute of the Product (item) entity." },
        def attribute channel    { type: text, isKey: true, description: "Sales channel the price applies to: 'web' or 'marketplace'." },
        def attribute valid_from { type: date, isKey: true, description: "First day the price is valid." },
        def attribute price      { type: { type: decimal, length: 12, precision: 2 }, description: "List price per unit." },
        def attribute valid_to   { type: date, description: "Last day the price is valid; empty while it is still valid." }
    ]
}

def entity customer_price {
    description: "Individual customer prices — a customer's own price of a product, valid from valid_from to valid_to; it beats the channel price list."
    labelPlural: "Customer Prices"
    roles: [master]
    displayLabel: { en: "Customer Price", cs: "Individuální cena" }
    attributes: [
        def attribute item       { type: int, isKey: true, description: "Priced product — FK to the 'sk' attribute of the Product (item) entity." },
        def attribute customer   { type: int, isKey: true, description: "Customer the price is agreed with — FK to the 'sk' attribute of the Customer entity." },
        def attribute valid_from { type: date, isKey: true, description: "First day the price is valid." },
        def attribute price      { type: { type: decimal, length: 12, precision: 2 }, description: "The customer's price per unit." },
        def attribute valid_to   { type: date, description: "Last day the price is valid; empty while it is still valid." }
    ]
}

def entity invoice {
    description: "Invoices — one per released order: amount, amount paid so far, due date. Status: open · paid; an open invoice past its due date is overdue."
    labelPlural: "Invoices"
    roles: [transaction]
    displayLabel: { en: "Invoice", cs: "Faktura" }
    attributes: [
        def attribute invoice_id   { type: int, isKey: true, description: "Invoice number." },
        def attribute customer     { type: int, description: "Invoiced customer — FK to the 'sk' attribute of the Customer entity." },
        def attribute order_number { type: int, description: "Invoiced order — FK to the 'order_number' attribute of the Order entity." },
        def attribute issued       { type: date, description: "The day the invoice was issued." },
        def attribute due          { type: date, description: "The day the invoice is due." },
        def attribute amount       { type: { type: decimal, length: 12, precision: 2 }, description: "Invoiced amount." },
        def attribute paid         { type: { type: decimal, length: 12, precision: 2 }, description: "Amount paid so far; amount − paid is still open." },
        def attribute status {
            type: text,
            description: "Payment status: 'open' or 'paid'.",
            states: [open, paid],                                    // AU D-67 — written by the ERP, never by a recipe
            valueLabels: {
                "open": { en: "Unpaid", cs: "Neuhrazeno" },
                "paid": { en: "Paid",   cs: "Uhrazeno" }
            }
        }
    ]
}

def entity warehouse_outage {
    description: "Distribution-center outages — a center that cannot ship from from_date to to_date (both days included), and why."
    labelPlural: "Warehouse Outages"
    roles: [transaction]
    // NOT „Výpadek“ (contracts §2 had it): a label is an EXACT term, and the bare «výpadek / výpadky» is the
    // demo's stockout word — «Kolik týdnů v roce 2025 mělo Brno DC výpadky zásob?» (act 3.5,
    // q.hartland.warehouse_stockout_week_count). The phrase keeps the word and leaves the bare one unclaimed.
    displayLabel: { en: "Warehouse Outage", cs: "Výpadek skladu" }
    attributes: [
        def attribute warehouse { type: int, isKey: true, description: "The distribution center that is out — FK to the 'sk' attribute of the Distribution Center (warehouse) entity." },
        def attribute from_date { type: date, isKey: true, description: "First day of the outage." },
        def attribute to_date   { type: date, description: "Last day of the outage." },
        def attribute reason    { type: text, description: "Why the center is out (free text)." }
    ]
}

files.model/er/parties.ttrm:
package hartland

model er

// Customers + their addresses/demographics, and Stores (D-5).

def entity customer {
    description: "Customers — the channel-overlap and demographic branches key off this entity."
    labelPlural: "Customers"
    // LP-P3·T1 (LP contracts §2.1) — the mention facet, CODE ONLY: this entity holds no
    // customer name (TPC-DS keeps first/last name out of the hartland cut), so a quoted
    // literal on this head attributes only when it is code-shaped. A plain quoted word stays
    // headless (G3) and the fast path refuses — correctly, and visibly.
    semantics { code: customer_id, code_pattern: "^[A-P]{16}$" }
    codeAttribute: customer_id
    roles: [master, dimension]
    displayLabel: { en: "Customer", cs: "Zákazník" }
    attributes: [
        def attribute sk          { type: int, isKey: true, description: "Sequence key. Internal primary key only." },
        def attribute customer_id { type: text, description: "Unique customer identifier (code)." },
        def attribute addr        { type: int, description: "Current address — FK to the 'sk' attribute of the Customer Address entity." },
        def attribute cdemo       { type: int, description: "Customer demographics — FK to the 'sk' attribute of the Customer Demographics entity." },
        def attribute hdemo       { type: int, description: "Household demographics — FK to the 'sk' attribute of the Household Demographics entity." },
        def attribute birth_year  { type: int, description: "Customer's year of birth — buyer-age analyses derive age from this." },
        // AU D-83 — derived by the data build from the modal warehouse of the customer's lines.
        def attribute center      { type: int, description: "The customer's distribution center — the one that ships most of their orders; FK to the 'sk' attribute of the Distribution Center (warehouse) entity. Empty for a customer with no web or marketplace order." }
    ]
}

def entity customer_address {
    description: "Customer addresses — the regional-dying branch (revenue-by-state, confirmed flat)."
    labelPlural: "Customer Addresses"
    // LP-P3·T1 (LP contracts §2.1) — the mention facet a quoted literal attributes to:
    // `"..."` on this head lands on `name`, a code-shaped literal on `code`. Without it the
    // literal is headless (G3) and the fast path refuses. The legacy properties below are
    // kept for the same reason store's are (readers before producers).
    semantics { name: city, code: address_id, code_pattern: "^[A-P]{16}$" }
    nameAttribute: city
    codeAttribute: address_id
    roles: [dimension]
    displayLabel: { en: "Customer Address", cs: "Adresa zákazníka" }
    attributes: [
        def attribute sk         { type: int, isKey: true, description: "Sequence key. Internal primary key only." },
        def attribute address_id { type: text, description: "Unique address identifier (code)." },
        def attribute city       { type: text, description: "City of the address." },
        def attribute county     { type: text, description: "County of the address." },
        // MH-P3 tier M — the `customers in TN` case: `customer` holds no state, this does, and
        // `customer_address` declares a relation TO `customer`, so the governor reaches it in
        // one hop. EXACT: two-character codes are all one edit apart.
        def attribute state      { type: { type: char, length: 2 }, description: "Two-letter US state code of the address — revenue-by-state slices use this.", search { searchable method: EXACT } }
    ]
}

def entity customer_demographics {
    description: "Customer demographics — the demographic-dying branch (buyer age, confirmed flat)."
    labelPlural: "Customer Demographics"
    roles: [dimension]
    displayLabel: { en: "Customer Demographics", cs: "Demografie zákazníka" }
    attributes: [
        def attribute sk             { type: int, isKey: true, description: "Sequence key. Internal primary key only." },
        def attribute gender         { type: { type: char, length: 1 }, description: "Gender code (M/F)." },
        def attribute marital_status { type: { type: char, length: 1 }, description: "Marital status code (single letter, e.g. S/M/D)." }
    ]
}

def entity household_demographics {
    description: "Household demographics — the demographic-dying branch."
    labelPlural: "Household Demographics"
    roles: [dimension]
    displayLabel: { en: "Household Demographics", cs: "Demografie domácnosti" }
    attributes: [
        def attribute sk            { type: int, isKey: true, description: "Sequence key. Internal primary key only." },
        def attribute income_band   { type: int, description: "Income band — FK to the 'sk' attribute of the Income Band entity." },
        def attribute buy_potential { type: text, description: "Household buying-potential label (e.g. '>10000', 'Unknown')." }
    ]
}

def entity income_band {
    description: "Income bands."
    labelPlural: "Income Bands"
    roles: [dimension]
    displayLabel: { en: "Income Band", cs: "Příjmové pásmo" }
    attributes: [
        def attribute sk          { type: int, isKey: true, description: "Sequence key. Internal primary key only." },
        def attribute lower_bound { type: int, description: "Lower bound of the household's yearly income range (USD)." },
        def attribute upper_bound { type: int, description: "Upper bound of the household's yearly income range (USD)." }
    ]
}

def entity store {
    // ttr-demo#62 remedy 3 (Bora, 2026-10-12): "How many stores do we have?" is 6, not 12. This
    // dimension is SCD type 2 — a store keeps its history as several rows, 12 rows for 6 stores
    // in both worlds — and a composer once answered COUNT(*). TTR-M says it in its own vocabulary
    // with the validity pair below (`valid_from`/`valid_to` on the row's history dates; the
    // business key is the mention facet's `code:`). Nothing reads that pair for a dimension yet
    // (money reads it for fx tables only), and the composer is shown an entity's FIRST
    // description line and no semantic role — so that line says how to count, in words.
    description: "Stores — the six stores (Stores-channel dim). SCD type 2: a store keeps its history as several rows (12 rows for the 6 stores), so count stores by store_id, or keep only the current rows (rec_end_date empty)."
    labelPlural: "Stores"
    // MS: the same two pointers in the vocabulary-v3 mention facet. The legacy properties
    // below are deliberately KEPT, which is why this entity raises TTR-SEM-218 ("both,
    // agreeing" — see model/tests/project-harness.mjs). Readers before producers: veles
    // reads `semantics { name:, code: }` only from MS-P2 on, and dropping the legacy
    // properties before the serving estate runs that build would blank
    // EntityDetail.name_attribute for this dimension. Delete them once hartland's veles
    // is on an MS-P2 image, not before.
    semantics { name: store_name, code: store_id, code_pattern: "^[A-P]{16}$" }
    nameAttribute: store_name
    codeAttribute: store_id
    roles: [dimension]
    displayLabel: { en: "Store", cs: "Prodejna" }
    attributes: [
        def attribute sk         { type: int, isKey: true, description: "Sequence key of one history row. Internal primary key only." },
        def attribute store_id   { type: text, description: "Unique store identifier (code) — the same on every history row of one store; count stores by it." },
        // MH-P3 tier M (E4) — `Nashville` is a store NAME, and a governed value has to be in
        // the member vocabulary before the governor can be asked about it. TYPOS(1) here: a
        // typed store name is a real word, not a two-letter code.
        def attribute store_name { type: text, description: "Store name, the human-readable label.", search { searchable method: TYPOS(1) } },
        def attribute city       { type: text, description: "The city the store is located in." },
        // MH-P3 tier M — the `stores in TN` case, and the one the drill leads with.
        def attribute state      { type: { type: char, length: 2 }, description: "The state the store is located in.", search { searchable method: EXACT } },
        // ttr-demo#62 — the SCD-2 validity pair (see the entity's comment).
        def attribute rec_start_date { type: date, semantics { role: valid_from }, description: "First day this history row describes the store." },
        def attribute rec_end_date   { type: date, semantics { role: valid_to }, description: "Last day this history row describes the store; empty on the current row." }
    ]
}

files.model/er/proposals.ttrm:
package hartland

model er

// AU (automation agents) — the H-3 / H-5 write-back entities. Empty at build: the recipes write them
// (`writable:` in the world file, D-79), the n8n purchasing workflow moves a proposal to `started`.

def entity reorder_proposal {
    description: "Reorder proposals — a product to reorder at a distribution center, proposed by the reorder recipe from stock on hand and weekly demand. State: proposed · approved · rejected · started."
    labelPlural: "Reorder Proposals"
    roles: [transaction]
    displayLabel: { en: "Reorder Proposal", cs: "Návrh na doobjednání" }
    attributes: [
        def attribute proposal_id   { type: int, isKey: true, description: "Proposal number." },
        def attribute run           { type: text, description: "The automation run that made the proposal." },
        def attribute item          { type: int, description: "Product to reorder — FK to the 'sk' attribute of the Product (item) entity." },
        def attribute warehouse     { type: int, description: "Distribution center to reorder for — FK to the 'sk' attribute of the Distribution Center (warehouse) entity." },
        def attribute on_hand       { type: int, description: "Units on hand when the proposal was made." },
        def attribute weekly_demand { type: { type: decimal, length: 12, precision: 2 }, description: "Average units sold per week at that center." },
        def attribute proposed_qty  { type: int, description: "Units proposed for reorder." },
        def attribute state {
            type: text,
            description: "Proposal state: 'proposed', 'approved', 'rejected' or 'started' (handed to purchasing).",
            states: [proposed, approved, rejected, started],         // AU D-67 — the writer proposes, the buyer's ask and purchasing move it
            valueLabels: {
                "proposed": { en: "Proposed",             cs: "Navrženo" },
                "approved": { en: "Approved",             cs: "Schváleno" },
                "rejected": { en: "Rejected",             cs: "Zamítnuto" },
                "started":  { en: "Handed to purchasing", cs: "Předáno nákupu" }
            }
        }
    ]
}

def entity winback_mail {
    description: "Win-back mailings — a lapsed customer the win-back recipe mailed an offer to, one per customer and quarter. Offer: premium · standard."
    labelPlural: "Win-back Mailings"
    roles: [transaction]
    displayLabel: { en: "Win-back Mailing", cs: "Win-back e-mail" }
    attributes: [
        def attribute customer  { type: int, isKey: true, description: "Mailed customer — FK to the 'sk' attribute of the Customer entity." },
        def attribute quarter   { type: text, isKey: true, description: "The quarter of the mailing, e.g. '2026-Q4'." },
        def attribute offer {
            type: text,
            description: "The offer mailed: 'premium' or 'standard'.",
            valueLabels: {
                "premium":  { en: "Premium offer",  cs: "Prémiová nabídka" },
                "standard": { en: "Standard offer", cs: "Standardní nabídka" }
            }
        },
        def attribute run       { type: text, description: "The automation run that mailed it." },
        def attribute mailed_at { type: timestamp, description: "When the mail was sent." }
    ]
}

