def relation rel_store_returns_store    { from: er.entity.store_returns, to: er.entity.store,    cardinality: { from: "0..*", to: "1" }, binding: { fk: db.dbo.fk_sr_store } }
def relation rel_store_returns_reason   { from: er.entity.store_returns, to: er.entity.reason,   cardinality: { from: "0..*", to: "1" }, binding: { fk: db.dbo.fk_sr_reason } }
def relation rel_store_returns_date     { from: er.entity.store_returns, to: er.entity.date_dim, cardinality: { from: "0..*", to: "1" }, binding: { fk: db.dbo.fk_sr_date } }

// -- web_returns --
def relation rel_web_returns_item     { from: er.entity.web_returns, to: er.entity.item,     cardinality: { from: "0..*", to: "1" }, binding: { fk: db.dbo.fk_wr_item } }
def relation rel_web_returns_customer { from: er.entity.web_returns, to: er.entity.customer, cardinality: { from: "0..*", to: "1" }, binding: { fk: db.dbo.fk_wr_customer } }
def relation rel_web_returns_reason   { from: er.entity.web_returns, to: er.entity.reason,   cardinality: { from: "0..*", to: "1" }, binding: { fk: db.dbo.fk_wr_reason } }
def relation rel_web_returns_date     { from: er.entity.web_returns, to: er.entity.date_dim, cardinality: { from: "0..*", to: "1" }, binding: { fk: db.dbo.fk_wr_date } }

// -- catalog_returns --
def relation rel_catalog_returns_item      { from: er.entity.catalog_returns, to: er.entity.item,      cardinality: { from: "0..*", to: "1" }, binding: { fk: db.dbo.fk_cr_item } }
def relation rel_catalog_returns_customer  { from: er.entity.catalog_returns, to: er.entity.customer,  cardinality: { from: "0..*", to: "1" }, binding: { fk: db.dbo.fk_cr_customer } }
def relation rel_catalog_returns_reason    { from: er.entity.catalog_returns, to: er.entity.reason,    cardinality: { from: "0..*", to: "1" }, binding: { fk: db.dbo.fk_cr_reason } }
def relation rel_catalog_returns_warehouse { from: er.entity.catalog_returns, to: er.entity.warehouse, cardinality: { from: "0..*", to: "1" }, binding: { fk: db.dbo.fk_cr_warehouse } }
def relation rel_catalog_returns_date      { from: er.entity.catalog_returns, to: er.entity.date_dim,  cardinality: { from: "0..*", to: "1" }, binding: { fk: db.dbo.fk_cr_date } }

// -- inventory --
def relation rel_inventory_item      { from: er.entity.inventory, to: er.entity.item,      cardinality: { from: "0..*", to: "1" }, binding: { fk: db.dbo.fk_inv_item } }
def relation rel_inventory_warehouse { from: er.entity.inventory, to: er.entity.warehouse, cardinality: { from: "0..*", to: "1" }, binding: { fk: db.dbo.fk_inv_warehouse } }
def relation rel_inventory_date      { from: er.entity.inventory, to: er.entity.date_dim,  cardinality: { from: "0..*", to: "1" }, binding: { fk: db.dbo.fk_inv_date } }

// -- customer's own dimension chains --
def relation rel_customer_addr  { from: er.entity.customer, to: er.entity.customer_address,        cardinality: { from: "0..*", to: "1" }, binding: { fk: db.dbo.fk_c_addr } }
def relation rel_customer_cdemo { from: er.entity.customer, to: er.entity.customer_demographics,    cardinality: { from: "0..*", to: "1" }, binding: { fk: db.dbo.fk_c_cdemo } }
def relation rel_customer_hdemo { from: er.entity.customer, to: er.entity.household_demographics,   cardinality: { from: "0..*", to: "1" }, binding: { fk: db.dbo.fk_c_hdemo } }

// -- household_demographics -> income_band --
def relation rel_household_demographics_income_band { from: er.entity.household_demographics, to: er.entity.income_band, cardinality: { from: "0..*", to: "1" }, binding: { fk: db.dbo.fk_hd_income } }

// -- channel_sales (all channels, view-backed) --
def relation rel_channel_sales_date     { from: er.entity.channel_sales, to: er.entity.date_dim, cardinality: { from: "0..*", to: "1" }, binding: { fk: db.dbo.fk_chs_date } }
def relation rel_channel_sales_item     { from: er.entity.channel_sales, to: er.entity.item,     cardinality: { from: "0..*", to: "1" }, binding: { fk: db.dbo.fk_chs_item } }
def relation rel_channel_sales_customer { from: er.entity.channel_sales, to: er.entity.customer, cardinality: { from: "0..*", to: "1" }, binding: { fk: db.dbo.fk_chs_customer } }
// LR ⚑LR-9 — NULLABLE: a store line has no distribution center, so joining drops store lines.
def relation rel_channel_sales_warehouse { from: er.entity.channel_sales, to: er.entity.warehouse, cardinality: { from: "0..*", to: "0..1" }, binding: { fk: db.dbo.fk_chs_warehouse } }

// ===== AU (automation agents) — the H-1/H-2 extension (orders.ttrm, returns-flow.ttrm, proposals.ttrm) =====
// contracts.md §2's relations, plus one per remaining extension fk that names a dimension (this file's
// rule: one relation per foreign key). `fk_rl_variant` gets NO relation: a second line → item relation
// would make every line/item join ambiguous; the requested variant is joined by value (17 §4.1).
//
// Each one also states its `join:` pair, which the relations above leave to the fk. The automation
// recipes join `on: relation X`, and that join condition — TTR-P's checker and the translator's
// JoinPolicy alike — is built from the relation's join pairs; a relation with only an fk has none there.

// -- order (sales_order) and its lines --
def relation rel_order_customer  { from: er.entity.order, to: er.entity.customer,  cardinality: { from: "0..*", to: "1" }, join: [{ from: er.entity.order.customer, to: er.entity.customer.sk }], binding: { fk: db.dbo.fk_so_customer } }
def relation rel_order_warehouse { from: er.entity.order, to: er.entity.warehouse, cardinality: { from: "0..*", to: "1" }, join: [{ from: er.entity.order.fulfilling_warehouse, to: er.entity.warehouse.sk }], binding: { fk: db.dbo.fk_so_warehouse } }
// The one relation whose "many" side is the TO side: an order has one or more lines. The fk lives on the
// many side (sales_line.sl_order_number); the key-lineage rule reads it as 1..* FROM the candidates'
// entity, so an `orders ⋈ sales_line on: relation rel_order_line` context stays keyed on the order (D-103).
def relation rel_order_line      { from: er.entity.order, to: er.entity.sales_line, cardinality: { from: "1", to: "1..*" }, join: [{ from: er.entity.order.order_number, to: er.entity.sales_line.order_number }], binding: { fk: db.dbo.fk_sl_order } }
def relation rel_sales_line_item      { from: er.entity.sales_line, to: er.entity.item,      cardinality: { from: "0..*", to: "1" }, join: [{ from: er.entity.sales_line.item, to: er.entity.item.sk }], binding: { fk: db.dbo.fk_sl_item } }
def relation rel_sales_line_customer  { from: er.entity.sales_line, to: er.entity.customer,  cardinality: { from: "0..*", to: "1" }, join: [{ from: er.entity.sales_line.customer, to: er.entity.customer.sk }], binding: { fk: db.dbo.fk_sl_customer } }
def relation rel_sales_line_warehouse { from: er.entity.sales_line, to: er.entity.warehouse, cardinality: { from: "0..*", to: "1" }, join: [{ from: er.entity.sales_line.warehouse, to: er.entity.warehouse.sk }], binding: { fk: db.dbo.fk_sl_warehouse } }

// -- prices, invoices, outages --
def relation rel_price_list_item         { from: er.entity.price_list,     to: er.entity.item,     cardinality: { from: "0..*", to: "1" }, join: [{ from: er.entity.price_list.item, to: er.entity.item.sk }], binding: { fk: db.dbo.fk_pl_item } }
def relation rel_customer_price_item     { from: er.entity.customer_price, to: er.entity.item,     cardinality: { from: "0..*", to: "1" }, join: [{ from: er.entity.customer_price.item, to: er.entity.item.sk }], binding: { fk: db.dbo.fk_cp_item } }
def relation rel_customer_price_customer { from: er.entity.customer_price, to: er.entity.customer, cardinality: { from: "0..*", to: "1" }, join: [{ from: er.entity.customer_price.customer, to: er.entity.customer.sk }], binding: { fk: db.dbo.fk_cp_customer } }
def relation rel_invoice_customer        { from: er.entity.invoice,        to: er.entity.customer, cardinality: { from: "0..*", to: "1" }, join: [{ from: er.entity.invoice.customer, to: er.entity.customer.sk }], binding: { fk: db.dbo.fk_inv_customer } }
def relation rel_invoice_order           { from: er.entity.invoice,        to: er.entity.order,    cardinality: { from: "0..*", to: "1" }, join: [{ from: er.entity.invoice.order_number, to: er.entity.order.order_number }], binding: { fk: db.dbo.fk_inv_order } }
def relation rel_outage_warehouse        { from: er.entity.warehouse_outage, to: er.entity.warehouse, cardinality: { from: "0..*", to: "1" }, join: [{ from: er.entity.warehouse_outage.warehouse, to: er.entity.warehouse.sk }], binding: { fk: db.dbo.fk_wo_warehouse } }

// -- customer's distribution center (D-83) — NULLABLE: a customer with no web/marketplace order has none --
def relation rel_customer_center { from: er.entity.customer, to: er.entity.warehouse, cardinality: { from: "0..*", to: "0..1" }, join: [{ from: er.entity.customer.center, to: er.entity.warehouse.sk }], binding: { fk: db.dbo.fk_c_center } }

// -- the return-request flow (the request reads a VIEW: its relations bind the view's logical keys) --
def relation rel_request_customer { from: er.entity.return_request, to: er.entity.customer, cardinality: { from: "0..*", to: "1" }, join: [{ from: er.entity.return_request.customer, to: er.entity.customer.sk }], binding: { fk: db.dbo.fk_rrv_customer } }
def relation rel_request_order    { from: er.entity.return_request, to: er.entity.order,    cardinality: { from: "0..*", to: "1" }, join: [{ from: er.entity.return_request.order_number, to: er.entity.order.order_number }], binding: { fk: db.dbo.fk_rrv_order } }
// A request has one or more lines — the to side is the many side, as in rel_order_line.
def relation rel_request_line     { from: er.entity.return_request, to: er.entity.return_request_line, cardinality: { from: "1", to: "1..*" }, join: [{ from: er.entity.return_request.request_number, to: er.entity.return_request_line.request_number }], binding: { fk: db.dbo.fk_rlv_request } }
// D-127 — one hop from the line to its customer (the line carries the request's customer).
def relation rel_line_customer    { from: er.entity.return_request_line, to: er.entity.customer, cardinality: { from: "0..*", to: "1" }, join: [{ from: er.entity.return_request_line.customer, to: er.entity.customer.sk }], binding: { fk: db.dbo.fk_rl_customer } }
def relation rel_line_item        { from: er.entity.return_request_line, to: er.entity.item,     cardinality: { from: "0..*", to: "1" }, join: [{ from: er.entity.return_request_line.item, to: er.entity.item.sk }], binding: { fk: db.dbo.fk_rl_item } }
def relation rel_receipt_line        { from: er.entity.return_receipt,       to: er.entity.return_request_line, cardinality: { from: "0..*", to: "1" }, join: [{ from: er.entity.return_receipt.line_id, to: er.entity.return_request_line.line_id }], binding: { fk: db.dbo.fk_rc_line } }
def relation rel_credit_note_line    { from: er.entity.credit_note,          to: er.entity.return_request_line, cardinality: { from: "0..*", to: "1" }, join: [{ from: er.entity.credit_note.line_id, to: er.entity.return_request_line.line_id }], binding: { fk: db.dbo.fk_cn_line } }
def relation rel_payment_credit_note { from: er.entity.refund_payment,       to: er.entity.credit_note,         cardinality: { from: "0..*", to: "1" }, join: [{ from: er.entity.refund_payment.credit_note_id, to: er.entity.credit_note.credit_note_id }], binding: { fk: db.dbo.fk_rp_credit_note } }
def relation rel_shipment_line       { from: er.entity.replacement_shipment, to: er.entity.return_request_line, cardinality: { from: "0..*", to: "1" }, join: [{ from: er.entity.replacement_shipment.line_id, to: er.entity.return_request_line.line_id }], binding: { fk: db.dbo.fk_rs_line } }

// -- the H-3/H-5 write-back entities --
def relation rel_proposal_item      { from: er.entity.reorder_proposal, to: er.entity.item,      cardinality: { from: "0..*", to: "1" }, join: [{ from: er.entity.reorder_proposal.item, to: er.entity.item.sk }], binding: { fk: db.dbo.fk_rp_item } }
def relation rel_proposal_warehouse { from: er.entity.reorder_proposal, to: er.entity.warehouse, cardinality: { from: "0..*", to: "1" }, join: [{ from: er.entity.reorder_proposal.warehouse, to: er.entity.warehouse.sk }], binding: { fk: db.dbo.fk_rp_warehouse } }
def relation rel_winback_customer   { from: er.entity.winback_mail,     to: er.entity.customer,  cardinality: { from: "0..*", to: "1" }, join: [{ from: er.entity.winback_mail.customer, to: er.entity.customer.sk }], binding: { fk: db.dbo.fk_wm_customer } }

// -- the documents' days: each dated document head reaches the calendar from its own date, as every fact does
// through its rel_*_date — so the composer's bare `JOIN date_dim` is conditioned by the model joins instead of
// left ON TRUE (the whole calendar under every document). One per document: a line dates with its order or its
// request (a second date path would make every order ⋈ line ⋈ date_dim join ambiguous); price lists and outages
// are ranges, proposals and win-back mails run artefacts.
def relation rel_order_date       { from: er.entity.order,                to: er.entity.date_dim, cardinality: { from: "0..*", to: "1" }, join: [{ from: er.entity.order.placed_date,                to: er.entity.date_dim.cal_date }], binding: { fk: db.dbo.fk_so_date } }
def relation rel_invoice_date     { from: er.entity.invoice,              to: er.entity.date_dim, cardinality: { from: "0..*", to: "1" }, join: [{ from: er.entity.invoice.issued,                   to: er.entity.date_dim.cal_date }], binding: { fk: db.dbo.fk_invoice_date } }
def relation rel_request_date     { from: er.entity.return_request,       to: er.entity.date_dim, cardinality: { from: "0..*", to: "1" }, join: [{ from: er.entity.return_request.requested_date,    to: er.entity.date_dim.cal_date }], binding: { fk: db.dbo.fk_rrv_date } }
def relation rel_receipt_date     { from: er.entity.return_receipt,       to: er.entity.date_dim, cardinality: { from: "0..*", to: "1" }, join: [{ from: er.entity.return_receipt.received_date,     to: er.entity.date_dim.cal_date }], binding: { fk: db.dbo.fk_rc_date } }
def relation rel_credit_note_date { from: er.entity.credit_note,          to: er.entity.date_dim, cardinality: { from: "0..*", to: "1" }, join: [{ from: er.entity.credit_note.issued_date,          to: er.entity.date_dim.cal_date }], binding: { fk: db.dbo.fk_cn_date } }
def relation rel_payment_date     { from: er.entity.refund_payment,       to: er.entity.date_dim, cardinality: { from: "0..*", to: "1" }, join: [{ from: er.entity.refund_payment.paid_date,         to: er.entity.date_dim.cal_date }], binding: { fk: db.dbo.fk_rp_paid_date } }
def relation rel_shipment_date    { from: er.entity.replacement_shipment, to: er.entity.date_dim, cardinality: { from: "0..*", to: "1" }, join: [{ from: er.entity.replacement_shipment.shipped_date, to: er.entity.date_dim.cal_date }], binding: { fk: db.dbo.fk_rs_date } }

files.model/er/returns-by-category.ttrm:
package hartland

model er

// BI-4 (project platform/features/bi, ⚑BI-4-A ruled by Bora 2026-10-22) — the logical query behind Superset's "Returns
// by category" dashboard, and the entity stacked on it (the LQ shape of customer_revenue.ttrm). One row per item
// category per month, over the return family: the request (its date), its lines (what is returned, for how much, where
// its handling stands) and the item (its category).
//
// BI's own, not SO's: the plan read the dashboard over `returns_review`, SO beat E's stacked entity, but SO keeps that
// on its pre-authored branch `demo/returns-review` and authors it live in the demo — a master object of that name would
// leave beat E's change nothing to add. So the name is this query's own, and SO's report joins the "one number" check
// when it reaches master.
//
// Parameterless (D-23), every month on record. No row rule narrows the return family (DC scope is on the stock and
// sales facts), so every persona reads the same rows: the persona contrast is the stock-out dashboard's.
//
// `requests` counts each request once per category and month: a request with lines in two categories counts in both,
// so it does not add up across categories (220,027 lines, 219,487 requests in either world). The month is its first
// day, the spelling stockouts.ttrm uses (DATE_TRUNC is not lowered yet, ttr-core#244).
//
// No declared phrase: the Golem answers returns questions over the return family itself («reklamace» is
// return_request's label), and a returns phrase here would take them from it. The label names the object.

def query returns_monthly_by_category {
    description: "Returns per item category per month, from the return requests: requests, lines, units, their value, and the lines still open. One row per category and month, every month on record."
    tags: ["returns", "categories"]
    sourceText: """sql
SELECT item.category AS category,
       CAST(CAST(EXTRACT(YEAR FROM return_request.requested_date) AS VARCHAR(4)) || '-' || CAST(EXTRACT(MONTH FROM return_request.requested_date) AS VARCHAR(2)) || '-01' AS DATE) AS month_start,
       COUNT(DISTINCT return_request_line.request_number) AS requests,
       COUNT(*) AS lines,
       SUM(return_request_line.quantity) AS units,
       SUM(return_request_line.quantity * return_request_line.unit_price) AS amount,
       SUM(CASE WHEN return_request_line.state IN ('closed', 'rejected') THEN 0 ELSE 1 END) AS open_lines
FROM return_request_line JOIN return_request JOIN item
GROUP BY item.category, CAST(CAST(EXTRACT(YEAR FROM return_request.requested_date) AS VARCHAR(4)) || '-' || CAST(EXTRACT(MONTH FROM return_request.requested_date) AS VARCHAR(2)) || '-01' AS DATE)
"""
}

// Stacked on the query: unbound attributes, each naming the output column of its own name. The category is a label,
// not a key of item, so the one relation is to the calendar day the month starts on.
def entity category_return_month {
    description: "Returns per item category per month — one row per category and month, from the return requests: how many requests and lines, units, their value (quantity × unit price) and the lines still open. Requests count once per category, so they do not add up across categories; lines, units and amount do. The month is its first day, so a year or a quarter narrows the months."
    roles: [fact]
    displayLabel: { en: "Monthly Returns by Category", cs: "Měsíční přehled reklamací podle kategorií" }
    semantics { measures: [ requests, amount ] }
    binding: { target: { query: er.query.returns_monthly_by_category } },
    attributes: [
        def attribute category    { type: text, isKey: true, description: "The returned item's category (Books, Music, …); empty for the few items with none." },
        def attribute month_start { type: date, isKey: true, description: "The month the return was requested, as its first day: 2026-07-01 is July 2026." },
        def attribute requests    { type: int, description: "Return requests with a line in this category, requested in the month." },
        def attribute lines       { type: int, description: "Returned lines in this category, requested in the month." },
        def attribute units       { type: int, description: "Units asked to be returned." },
        def attribute amount      { type: { type: decimal, length: 14, precision: 2 }, description: "Value of the returned lines: quantity × the unit price the customer paid." },
        def attribute open_lines  { type: int, description: "Lines still being handled: neither closed nor rejected." }
    ]
}

def relation rel_category_return_month_date {
    description: "A month's returns are dated by the first day of the month they were requested in."
    from: er.entity.category_return_month, to: er.entity.date_dim,
    cardinality: { from: "0..*", to: "1" },
    join: [{ from: er.entity.category_return_month.month_start, to: er.entity.date_dim.cal_date }]
}

files.model/er/returns-flow.ttrm:
package hartland

model er

// AU (automation agents) — the H-2 return-request flow (D-79, D-84), the entity table of
// project/kantheon/features/automation-agents/design/17-recipes-retyped.md §0.
//
// The flow is keyed on the LINE (D-84): the recipes decide, monitor and settle one return_request_line
// at a time; the request's own state is DERIVED from its lines (the return_request view) and nothing
// writes it. The four document entities are written by the ERP — the data generator, live the n8n ERP
// workflow — and only ever EXPECTED by the recipes (D-79).
//
// ⚠ These are not the returns FACTS. Return value and volume by channel stay with store_returns /
// web_returns / catalog_returns («vratky», «reklamace» as a measure — ttr-demo#62); nothing here
// declares `semantics { measures }`.

def entity return_request {
    description: "Return requests — a customer's request to return goods from one order (the header); its lines carry what is returned. State, derived from the lines: received (a line still waits for a decision) · decided · closed (every line rejected, not returned or closed)."
    labelPlural: "Return Requests"
    roles: [transaction]
    displayLabel: { en: "Return Request", cs: "Reklamace" }
    attributes: [
        def attribute request_number { type: int, isKey: true, description: "Return request number." },
        def attribute customer       { type: int, description: "Returning customer — FK to the 'sk' attribute of the Customer entity." },
        def attribute order_number   { type: int, description: "The order the goods were bought on — FK to the 'order_number' attribute of the Order entity." },
        def attribute channel        { type: text, description: "Sales channel of the request: 'web' or 'marketplace'." },
        def attribute requested_date { type: date, description: "The day the return was requested." },
        def attribute state {
            type: text,
            description: "State of the request, derived from its lines (read-only): 'received', 'decided' or 'closed'.",
            valueLabels: {
                "received": { en: "Received", cs: "Přijato" },
                "decided":  { en: "Decided",  cs: "Rozhodnuto" },
                "closed":   { en: "Closed",   cs: "Uzavřeno" }
            }
        }
    ]
}

def entity return_request_line {
    description: "Return request lines — one returned product of a return request, and where its handling stands. State: received · rejected · settling · awaiting_goods · goods_received · not_returned · closed."
    labelPlural: "Return Request Lines"
    roles: [transaction]
    displayLabel: { en: "Return Request Line", cs: "Řádek reklamace" }
    attributes: [
        def attribute line_id              { type: int, isKey: true, description: "Return line number — the key every return decision and obligation is about." },
        def attribute request_number       { type: int, description: "The line's return request — FK to the 'request_number' attribute of the Return Request entity." },
        def attribute line_no              { type: int, description: "Line number within the request." },
        def attribute item                 { type: int, description: "Returned product — FK to the 'sk' attribute of the Product (item) entity." },
        def attribute quantity             { type: int, description: "Units to return." },
        def attribute unit_price           { type: { type: decimal, length: 12, precision: 2 }, description: "Unit price the customer paid — quantity × unit price is the line's value." },
        def attribute reason {
            type: text,
            description: "Why the customer returns it: 'damaged', 'did_not_arrive', 'wrong_size' or 'other'.",
            valueLabels: {
                "damaged":        { en: "Arrived damaged",   cs: "Dorazilo poškozené" },
                "did_not_arrive": { en: "Never arrived",     cs: "Zásilka nedorazila" },
                "wrong_size":     { en: "Size does not fit", cs: "Nevhodná velikost" },
                "other":          { en: "Another reason",    cs: "Jiná příčina" }
            }
        },
        def attribute requested_resolution {
            type: text,
            description: "What the customer asks for: 'refund', 'exchange' or 'replacement'.",
            valueLabels: {
                "refund":      { en: "Refund",      cs: "Vrácení peněz" },
                "exchange":    { en: "Exchange",    cs: "Výměna" },
                "replacement": { en: "Replacement", cs: "Náhrada" }
            }
        },
        def attribute requested_variant    { type: int, description: "The product asked for in an exchange — FK to the 'sk' attribute of the Product (item) entity; empty otherwise." },
        def attribute state {
            type: text,
            description: "Handling state of the line: 'received', 'rejected', 'settling', 'awaiting_goods', 'goods_received', 'not_returned' or 'closed'.",
            // AU D-67 — the H-2 graph (17 §4): decide_return moves a received line, monitor_inbound an awaiting one,
            // settle closes; rejected, not_returned and closed are final.
            states: [received, rejected, settling, awaiting_goods, goods_received, not_returned, closed],
            transitions: { received: [rejected, settling, awaiting_goods], awaiting_goods: [goods_received, not_returned],
                           settling: [closed], goods_received: [closed] },
            valueLabels: {
                "received":       { en: "Received",       cs: "Přijato" },
                "rejected":       { en: "Rejected",       cs: "Zamítnuto" },
                "settling":       { en: "Settling",       cs: "Vyřizuje se" },
                "awaiting_goods": { en: "Awaiting goods", cs: "Čeká na zboží" },
                "goods_received": { en: "Goods received", cs: "Zboží přijato" },
                "not_returned":   { en: "Not returned",   cs: "Nevráceno" },
                "closed":         { en: "Closed",         cs: "Uzavřeno" }
            }
        },
        def attribute way {
            type: text,
            description: "How the line is being settled, once decided: 'refund_no_return', 'replacement_no_return', 'exchange' or 'refund_after_return'; empty until decided or when rejected.",
            valueLabels: {
                "refund_no_return":      { en: "Refund without return",      cs: "Vrácení peněz bez vratky" },
                "replacement_no_return": { en: "Replacement without return", cs: "Náhrada bez vratky" },
                "exchange":              { en: "Exchange",                   cs: "Výměna" },
                "refund_after_return":   { en: "Refund after return",        cs: "Vrácení peněz po vratce" }
            }
        },
        // D-127 — the request's customer, denormalized onto the line by the generator: rel_line_customer is one hop.
        def attribute customer             { type: int, description: "Returning customer (the request's) — FK to the 'sk' attribute of the Customer entity." }
    ]
}

def entity return_receipt {
    description: "Return receipts — returned goods received back at the warehouse for a return line, and in what condition: ok · damaged · missing."
    labelPlural: "Return Receipts"
    roles: [transaction]
    // NOT „Vratka“ (contracts §2 had it): ttr-demo#62 ruled the bare «vratka / vratky» a word of the three
    // channels' returns measures that must not pick one entity (lexicon/tests/store-family.test.mjs), and a
    // label is an EXACT metadata term. „Příjemka vratky“ — the warehouse receipt of a return — is a phrase.
    displayLabel: { en: "Return Receipt", cs: "Příjemka vratky" }
    attributes: [
        def attribute receipt_id    { type: int, isKey: true, description: "Receipt number." },
        def attribute line_id       { type: int, description: "The return line received — FK to the 'line_id' attribute of the Return Request Line entity." },
        def attribute received_date { type: date, description: "The day the goods arrived." },
        def attribute item          { type: int, description: "Received product — FK to the 'sk' attribute of the Product (item) entity." },
        def attribute quantity      { type: int, description: "Units received." },
        def attribute condition {
            type: text,
            description: "Condition of the received goods: 'ok', 'damaged' or 'missing'.",
            valueLabels: {
                "ok":      { en: "In order",      cs: "V pořádku" },
                "damaged": { en: "Damaged goods", cs: "Poškozené zboží" },
                "missing": { en: "Goods missing", cs: "Zboží chybí" }
            }
        }
    ]
}

def entity credit_note {
    description: "Credit notes — the money owed back to a customer for a return line. Status: issued · paid."
    labelPlural: "Credit Notes"
    roles: [transaction]
    displayLabel: { en: "Credit Note", cs: "Dobropis" }
    attributes: [
        def attribute credit_note_id { type: int, isKey: true, description: "Credit note number." },
        def attribute line_id        { type: int, description: "The return line credited — FK to the 'line_id' attribute of the Return Request Line entity." },
        def attribute customer       { type: int, description: "Credited customer — FK to the 'sk' attribute of the Customer entity." },
        def attribute issued_date    { type: date, description: "The day the credit note was issued." },
        def attribute amount         { type: { type: decimal, length: 12, precision: 2 }, description: "Credited amount." },
        def attribute status {
            type: text,
            description: "Status of the credit note: 'issued' or 'paid'.",
            valueLabels: {
                "issued": { en: "Issued",   cs: "Vystaveno" },
                "paid":   { en: "Paid out", cs: "Vyplaceno" }
            }
        }
    ]
}

def entity refund_payment {
    description: "Refund payments — money paid out to a customer against a credit note."
    labelPlural: "Refund Payments"
    roles: [transaction]
    displayLabel: { en: "Refund Payment", cs: "Úhrada" }
    attributes: [
        def attribute payment_id     { type: int, isKey: true, description: "Payment number." },
        def attribute credit_note_id { type: int, description: "The credit note paid — FK to the 'credit_note_id' attribute of the Credit Note entity." },
        def attribute paid_date      { type: date, description: "The day the refund was paid." },
        def attribute amount         { type: { type: decimal, length: 12, precision: 2 }, description: "Amount paid." }
    ]
}

def entity replacement_shipment {
    description: "Replacement shipments — replacement goods shipped to a customer for a return line."
    labelPlural: "Replacement Shipments"
    roles: [transaction]
    displayLabel: { en: "Replacement Shipment", cs: "Náhradní zásilka" }
    attributes: [
        def attribute shipment_id  { type: int, isKey: true, description: "Shipment number." },
        def attribute line_id      { type: int, description: "The return line replaced — FK to the 'line_id' attribute of the Return Request Line entity." },
        def attribute item         { type: int, description: "Shipped product — FK to the 'sk' attribute of the Product (item) entity." },
        def attribute quantity     { type: int, description: "Units shipped." },
        def attribute shipped_date { type: date, description: "The day the replacement was shipped." }
    ]
}

def entity document_flow {
    description: "Document flow of returns — which document followed which: order → return request → receipt, credit note, replacement shipment; credit note → refund payment. A kind is the entity name of the document."
    labelPlural: "Document Flow"
    roles: [bridge]
    displayLabel: { en: "Document Flow", cs: "Tok dokladů" }
    attributes: [
        def attribute pred_kind { type: text, isKey: true, description: "Kind of the preceding document: 'order', 'return_request' or 'credit_note'." },
        def attribute pred_id   { type: int, isKey: true, description: "Number of the preceding document." },
        def attribute succ_kind { type: text, isKey: true, description: "Kind of the following document: 'return_request', 'return_receipt', 'credit_note', 'refund_payment' or 'replacement_shipment'." },
        def attribute succ_id   { type: int, isKey: true, description: "Number of the following document." }
    ]
}

files.model/er/returns.ttrm:
package hartland

model er

// Channel returns entities + the Return Reasons dim (D-5). return_amt is deliberately
// the SAME logical name across all three returns entities even though the physical
// column is cr_return_amount (not cr_return_amt) on catalog_returns — the er2db binding
// (Stage 2.2 T2) absorbs that naming inconsistency so md-layer measures (Stage 2.4) can
// treat the three symmetrically.

def entity store_returns {
    description: "Stores-channel returns."
    labelPlural: "Store Returns"
    roles: [fact]
    displayLabel: { en: "Store Returns", cs: "Reklamace z prodejen" }
    // MS: the mention facet. return_amt FIRST — a bare "reklamace" asks about the
    // refunded value, and the rate beat divides it by ext_sales_price.
    semantics { measures: [ return_amt, return_quantity ] }
    attributes: [
        def attribute item            { type: int, isKey: true, description: "Returned product — FK to the 'sk' attribute of the Product (item) entity." },
        def attribute ticket_number   { type: int, isKey: true, description: "Original sales ticket number — pairs this return with its sale." },
        def attribute returned_date   { type: int, description: "Return date — FK to the 'sk' attribute of the Calendar (date_dim) entity." },
        def attribute customer        { type: int, description: "Returning customer — FK to the 'sk' attribute of the Customer entity." },
        def attribute store           { type: int, description: "Store accepting the return — FK to the 'sk' attribute of the Store entity." },
        def attribute reason          { type: int, description: "Return reason — FK to the 'sk' attribute of the Return Reason entity." },
        def attribute return_quantity { type: int, description: "Units returned on this line." },
        def attribute return_amt      { type: { type: decimal, length: 10, precision: 2 }, description: "Refunded amount of the line — SUM this for the return value; ratio against ext_sales_price gives the return rate." }
    ]
}

def entity web_returns {
    description: "Web-channel returns."
    labelPlural: "Web Returns"
    roles: [fact]
    displayLabel: { en: "Web Returns", cs: "Reklamace z webu" }
    // MS: the mention facet — the three returns entities stay symmetric here too.
    semantics { measures: [ return_amt, return_quantity ] }
    attributes: [
        def attribute item            { type: int, isKey: true, description: "Returned product — FK to the 'sk' attribute of the Product (item) entity." },
        def attribute order_number    { type: int, isKey: true, description: "Original web order number — pairs this return with its sale." },
        def attribute returned_date   { type: int, description: "Return date — FK to the 'sk' attribute of the Calendar (date_dim) entity." },
        def attribute customer        { type: int, description: "Returning customer — FK to the 'sk' attribute of the Customer entity." },
        def attribute reason          { type: int, description: "Return reason — FK to the 'sk' attribute of the Return Reason entity." },
        def attribute return_quantity { type: int, description: "Units returned on this line." },
        def attribute return_amt      { type: { type: decimal, length: 10, precision: 2 }, description: "Refunded amount of the line — SUM this for the return value; ratio against ext_sales_price gives the return rate." }
    ]
}

def entity catalog_returns {
    description: "Marketplace-channel returns — S3's paired evidence signal alongside the inventory stockout."
    labelPlural: "Marketplace Returns"
    roles: [fact]
    displayLabel: { en: "Marketplace Returns", cs: "Reklamace z tržiště" }
    // MS: the mention facet — S3's paired signal is asked about by value, so return_amt
    // leads here as it does on the other two channels.
    semantics { measures: [ return_amt, return_quantity ] }
    attributes: [
        def attribute item            { type: int, isKey: true, description: "Returned product — FK to the 'sk' attribute of the Product (item) entity." },
        def attribute order_number    { type: int, isKey: true, description: "Original marketplace order number — pairs this return with its sale." },
        def attribute returned_date   { type: int, description: "Return date — FK to the 'sk' attribute of the Calendar (date_dim) entity." },
        def attribute customer        { type: int, description: "Returning customer — FK to the 'sk' attribute of the Customer entity." },
        def attribute reason          { type: int, description: "Return reason — FK to the 'sk' attribute of the Return Reason entity." },
        def attribute warehouse       { type: int, description: "Distribution center processing the return — FK to the 'sk' attribute of the Distribution Center (warehouse) entity." },
        def attribute return_quantity { type: int, description: "Units returned on this line." },
        def attribute return_amt      { type: { type: decimal, length: 10, precision: 2 }, description: "Refunded amount of the line — SUM this for the return value; ratio against ext_sales_price gives the return rate." }
    ]
}

def entity reason {
    // The incident's late-delivery signal is one of these reasons. Its text is world-specific
    // (US "Did not get it on time", CZ "Nedorazilo včas"), so no description below names a value:
    // the model serves both worlds (BM-8), and the composer copied the US example into SQL on the
    // CZ world (0 rows, 2026-10-10).
    description: "Return reasons — why a customer returned a sales line. The reason text is stored in the language of the loaded data."
    labelPlural: "Return Reasons"
    // LP-P3·T1 (LP contracts §2.1) — the mention facet a quoted literal attributes to:
    // `"..."` on this head lands on `name`, a code-shaped literal on `code`. Without it the
    // literal is headless (G3) and the fast path refuses. The legacy properties below are
    // kept for the same reason store's are (readers before producers).
    semantics { name: reason_desc, code: reason_id, code_pattern: "^[A-P]{16}$" }
    nameAttribute: reason_desc
    codeAttribute: reason_id
    roles: [dimension]
    displayLabel: { en: "Return Reason", cs: "Důvod reklamace" }
    attributes: [
        def attribute sk          { type: int, isKey: true, description: "Sequence key. Internal primary key only." },
        def attribute reason_id   { type: text, description: "Return reason identifier (code)." },
        // Member vocabulary, TOKENS: 35 reasons, each a short phrase — «better price» finds 'Found a better price'.
        def attribute reason_desc { type: text, description: "Return reason text, the human-readable label, in the language of the loaded data. Filter on the reason exactly as the question names it, never on a translation of it.", search { searchable method: TOKENS } }
    ]
}

files.model/er/sales.ttrm:
package hartland

model er

// Channel sales entities (D-5). Attribute names are logical — physical table-prefix
// stripped (ss_/ws_/cs_) — the whole point of the er layer vs raw db columns. D-6's
// channel-vocabulary structure (T4) is these three distinct entities + labelPlural/
// displayLabel; the actual synonym forms (`aliases:` is legacy — flagged by
// ttr/lexicon-legacy-aliases, "declare a lexicon `term`" instead) are Stage 2.5's lexicon.

def entity store_sales {
    description: "Stores-channel sales lines — store / brick-and-mortar revenue (sales) = SUM(ext_sales_price), units sold = quantity, dated by sold_date."
    labelPlural: "Store Sales"
    roles: [fact]
    // ttr-demo#62 (2026-10-14): the Czech label names the FACT, like the en "Store Sales" and the
    // other channels' „Webové objednávky“ / „Objednávky z tržiště“. It used to be „Tržby z prodejen“
    // — the measure phrase — and a label is a METADATA term matched EXACT at 1.168 on three words,
    // so «Tržby z prodejen za 2025» bound this ENTITY instead of its revenue, the door could not
    // answer, and the composer ran a 3-channel monthly query. No declared term can outrank that
    // (a profiled EXACT scores 1.000, a TOKENS phrase is a class below), so the phrase moved to
    // `lexicon/aliases/hartland.lex.yaml`, on the measure, beside its singular.
    displayLabel: { en: "Store Sales", cs: "Prodeje v prodejnách" }
    // MS (mention semantics, vocabulary v3): the MENTION facet — what a human is asking
    // for when they mention this entity. Declared order is load-bearing: ext_sales_price
    // is FIRST, so revenue is the default measure of a bare "store sales". Both are
    // `sum`, which is the bare-id default, so neither needs an item object. This is what
    // makes store_sales resolve as `entity_with_measures` rather than a plain `entity`,
    // which is what wakes FrameRoles R2 and the R3–R6 `podle`/"by" exemptions.
    semantics { measures: [ ext_sales_price, quantity ] }
    attributes: [
        def attribute item           { type: int, isKey: true, description: "Sold product — FK to the 'sk' attribute of the Product (item) entity." },
        def attribute ticket_number  { type: int, isKey: true, description: "Sales ticket number; one ticket = one basket. Part of the primary key." },
        def attribute sold_date      { type: int, description: "Sale date — FK to the 'sk' attribute of the Calendar (date_dim) entity." },
        def attribute customer       { type: int, description: "Buying customer — FK to the 'sk' attribute of the Customer entity." },
        def attribute addr           { type: int, description: "Customer address at sale time — FK to the 'sk' attribute of the Customer Address entity." },
        def attribute store          { type: int, description: "Selling store — FK to the 'sk' attribute of the Store entity." },
        def attribute promo          { type: int, description: "Promotion applied to this line, if any — FK to the 'sk' attribute of the Promotion entity." },
        def attribute quantity       { type: int, description: "Units sold on this line." },
        def attribute ext_sales_price { type: { type: decimal, length: 10, precision: 2 }, description: "Extended sales price of the line (unit price × quantity) — the revenue amount; SUM this for revenue/sales." }
    ]
}

def entity web_sales {
    description: "Web-channel sales lines — web / online / e-shop revenue (sales) = SUM(ext_sales_price), units sold = quantity, dated by sold_date."
    labelPlural: "Web Orders"
    roles: [fact]
    displayLabel: { en: "Web Orders", cs: "Webové objednávky" }
    // MS: the mention facet, same shape and same reason as store_sales above —
    // ext_sales_price FIRST, so revenue is the default measure of a bare "tržby z webu".
    semantics { measures: [ ext_sales_price, quantity ] }
    attributes: [
        def attribute item           { type: int, isKey: true, description: "Sold product — FK to the 'sk' attribute of the Product (item) entity." },
        def attribute order_number   { type: int, isKey: true, description: "Web order number; one order = one basket. Part of the primary key." },
        def attribute sold_date      { type: int, description: "Sale date — FK to the 'sk' attribute of the Calendar (date_dim) entity." },
        def attribute customer       { type: int, description: "Buying customer — FK to the 'sk' attribute of the Customer entity." },
        def attribute addr           { type: int, description: "Customer address at sale time — FK to the 'sk' attribute of the Customer Address entity." },
        def attribute warehouse      { type: int, description: "Fulfilling distribution center — FK to the 'sk' attribute of the Distribution Center (warehouse) entity." },
        def attribute promo          { type: int, description: "Promotion applied to this line, if any — FK to the 'sk' attribute of the Promotion entity." },
        def attribute quantity       { type: int, description: "Units sold on this line." },
        def attribute ext_sales_price { type: { type: decimal, length: 10, precision: 2 }, description: "Extended sales price of the line (unit price × quantity) — the revenue amount; SUM this for revenue/sales." }
    ]
