files.model/md/domains.ttrm:
package hartland

model md

// Typed domains (Stage 2.3 T1). Money is currency-agnostic (the USD/CZK label rides the
// lexicon locale, Stage 2.5; the FX-scaled values ride the DB, Phase 1) — per
// tests-p2-overview.md's verified-correctness note: TTR-M has no per-connection currency
// unit. Coded domains are kept OPEN strings (no `restrict: members`) — the on-screen
// member labels are the lexicon's `valueLabels` (Stage 2.5), not modeled here, so both
// worlds share one domain definition.

// -- measures' value types --
def domain Money    { type: decimal }
def domain Quantity { type: int }

// -- calendar (the one family that must be calc, per map-catalog.md — no non-time
// calc maps ship in v1) --
def domain Day     { type: date }
def domain Month   { type: int, kind: calc, restrict: { range: 1..12 } }
def domain Quarter { type: int, kind: calc, restrict: { range: 1..4 } }
def domain Year    { type: int, kind: calc }
def domain Week    { type: int, kind: calc, restrict: { range: 1..53 } }

// -- Product (BM-5: Category -> Class -> Brand -> Manufacturer -> Item) --
def domain ItemCode         { type: string }
def domain ProductName      { type: string }
def domain ClassCode        { type: string }
def domain BrandCode        { type: string }
def domain ManufacturerCode { type: string }
def domain CategoryCode     { type: string }

// -- Customer / geography --
def domain CustomerCode { type: string }
def domain AddressCode  { type: string }   // customer's current-address FK (c_current_addr_sk) —
                                           // the intermediate join hop CustomerCode -> AddressCode -> State
def domain State        { type: string }
def domain BirthYear    { type: int }      // c_birth_year; buyer AGE is derived at query time
                                           // (:year - birth_year, query #12) — TPC-DS stores no age
                                           // band, so birth year is the honest physical source

// -- Store --
def domain StoreCode { type: string }
def domain StoreName { type: string }

// -- Distribution Centre --
def domain DcCode { type: string }
def domain DcName { type: string }

// -- Promotion --
def domain PromoCode { type: string }
def domain PromoName { type: string }

// -- Return Reason ("Nedorazilo včas" / "Did not get it on time" lives here, valueLabels in 2.5) --
def domain ReasonCode { type: string }
def domain ReasonDesc { type: string }

files.model/md/measures.ttrm:
package hartland

model md

// D-6/D-6a measure set — revenue, quantity, order/line counts, return amount, on-hand
// qty ONLY. revenue/returnAmount share the currency-agnostic Money domain (Stage 2.3) —
// the USD/CZK label is a lexicon/connection display fact (Stage 2.5 / connections.toml),
// never a second measure (T4). No net_profit/margin/cost measure: the domains to build
// one don't exist and the underlying db columns aren't modeled (Stage 2.1 T4).

def measure revenue      { domain: md.Money,    class: additive, aggregation: sum }
def measure quantity     { domain: md.Quantity, class: additive, aggregation: sum }
def measure orderCount   { domain: md.Quantity, class: additive, aggregation: countDistinct }
def measure lineCount    { domain: md.Quantity, class: additive, aggregation: count }
def measure returnAmount { domain: md.Money,    class: additive, aggregation: sum }

// Weekly on-hand snapshot — semi-additive (doesn't sum meaningfully across weeks), the
// smoking gun behind S1 (17-week zero streak at the meltdown DC).
def measure onHandQty {
    domain: md.Quantity,
    class: semiAdditive,
    aggregation: { default: sum, time: latestValid },
    validBy: week
}

files.model/md/product.ttrm:
package hartland

model md

// Product (Stage 2.3 T2/T3) — the 5-level BM-5 hierarchy the bilingual catalog (Phase 1)
// lit up: Category -> Class -> Brand -> Manufacturer -> Item. TPC-DS's `item` row
// denormalizes category/class/brand/manufacturer on ONE row (no separate brand/category
// tables), so every step is table-backed (no `calc:`) with an N:1 cardinality declared
// explicitly — the case columns arrive via `md2db_map` in Stage 2.4.
//
// Verification note carried to Phase 3: N:1 (each brand rolls up to exactly one
// manufacturer, each class to one category, etc.) is a MODELING decision BM-5 made for a
// clean demo drill, not a guarantee the deterministic generator (data/catalog/generate.py)
// enforces at the row level — live-DB verification of the rollup's actual consistency is
// a Phase 3 H3 concern, not a Stage 2.3 blocker (mocked/structural only here).

// categoryCode's physical value (i_category) is the SAME stable English string on both
// hartland_us and hartland_cz (Phase 1 catalog generator kept the category code
// locale-invariant; only class/brand/product_name are localized text) — so it's the code
// valueLabels keys on, per data/catalog/value-labels.json "category" group (Stage 2.5 T3).
def dimension Product {
    key: itemCode,
    attributes: [
        def attribute itemCode         { domain: md.ItemCode, isKey: true },
        def attribute productName      { domain: md.ProductName },
        def attribute classCode        { domain: md.ClassCode },
        def attribute brandCode        { domain: md.BrandCode },
        def attribute manufacturerCode { domain: md.ManufacturerCode },
        def attribute categoryCode {
            domain: md.CategoryCode,
            valueLabels: {
                "Books": { en: "Books", cs: "Knihy" },
                "Children": { en: "Children", cs: "Dětské" },
                "Electronics": { en: "Electronics", cs: "Elektronika" },
                "Home": { en: "Home", cs: "Domácnost" },
                "Jewelry": { en: "Jewelry", cs: "Šperky" },
                "Men": { en: "Men", cs: "Pánské" },
                "Music": { en: "Music", cs: "Hudba" },
                "Shoes": { en: "Shoes", cs: "Obuv" },
                "Sports": { en: "Sports", cs: "Sport" },
                "Women": { en: "Women", cs: "Dámské" }
            }
        }
    ],
    hierarchies: [productDrill]
}

def map item_to_manuf    { from: md.ItemCode,         to: md.ManufacturerCode, cardinality: { from: "N", to: "1" } }
def map manuf_to_brand   { from: md.ManufacturerCode, to: md.BrandCode,        cardinality: { from: "N", to: "1" } }
def map brand_to_class   { from: md.BrandCode,        to: md.ClassCode,        cardinality: { from: "N", to: "1" } }
def map class_to_category { from: md.ClassCode,       to: md.CategoryCode,     cardinality: { from: "N", to: "1" } }

// Product's descriptive label (not a drill level) — the item's display name, bound in md2db.ttrm.
def map item_to_name     { from: md.ItemCode,         to: md.ProductName,      cardinality: { from: "N", to: "1" } }

def hierarchy productDrill {
    dimension: md.Product,
    levels: [
        itemCode,
        manufacturerCode via md.item_to_manuf,
        brandCode via md.manuf_to_brand,
        classCode via md.brand_to_class,
        categoryCode via md.class_to_category
    ]
}

files.model/queries/q_hartland.ttrm:
package hartland

model query

// q.hartland.* #1-15 (D-2). Every query is literal `language: SQL` sourceText against the
// physical db layer (Stage 2.1) — the grammar has no "language: MD"/dot-path query form
// (languageValue: SQL | TRANSFORMATION_DSL | DATAFRAME_DSL | REL_NODE), and Stage 2.3
// already found the MD dot-path drill notation is unimplemented design-stage sugar. The
// "re-expressed on the md star" framing in the plan is a future-state aspiration, not
// buildable against the current grammar — noted here rather than silently deviating.
//
// "channel?" (optional) params from the D-2 table are NOT baked into the SQL as a
// parameter — per D-2's own note, chip amendments ("only Marketplace") ride the
// Filter/Project/Sort STACK over a channel-labeled UNION ALL result, not a new query or a
// required param. Where D-2 marks channel REQUIRED (no "?": #3/#6/#11/#12/#13), the SQL
// takes a required `:channel` param filtering a channel-labeled CTE instead. Year params
// default 2021-2026 (post-redate) at the caller/UI layer, not encoded in sourceText.
//
// No query touches profit/cost (D-6a) — the physical columns aren't modeled (Stage 2.1 T4)
// so there is nothing to join/select even if a query tried.

def query channel_revenue_monthly {
    // Demo notes (not shown to users): beats 1-2 charts, Metis input series.
    //
    // LR 2026-10-10 — `channel` is REQUIRED (D-2 had it optional, riding a chip stack nobody built).
    // Without it the query could only answer every channel, and the composer used it for a
    // one-channel question (the Czech demo's 1.4a, „trzby z trziste … po mesicich“ → 36 rows for
    // store, web AND marketplace). TTR-M query parameters have no default, so "all channels" is the
    // explicit value `all`: a broader answer is now a decision the plan states, never an accident,
    // and an unstated channel asks the user (param_fill) instead of answering a wider question.
    description: {
        en: "Monthly revenue by channel. One row per channel, year and month, for a range of years; channel is store, web, marketplace, or all for every channel.",
        cs: "Měsíční tržby podle kanálu. Jeden řádek za kanál, rok a měsíc pro zvolený rozsah let; kanál je store, web, marketplace, nebo all pro všechny kanály."
    }
    language: SQL
    sourceText: """
        WITH monthly AS (
            SELECT CAST('store' AS VARCHAR(16)) AS channel, d.d_year, d.d_moy, SUM(ss.ss_ext_sales_price) AS revenue
            FROM store_sales ss JOIN date_dim d ON ss.ss_sold_date_sk = d.d_date_sk
            WHERE d.d_year BETWEEN {year_from} AND {year_to}
            GROUP BY d.d_year, d.d_moy
            UNION ALL
